function runbookWorkflowItems(params) {
  // Async (CMP registers it with isAsync). Add it to any blueprint custom form
  // that has Run Workflow build items: it finds each item's Workflow question
  // (plugin-bdi-<id>.workflow, a dropdown, or a hidden question whose
  // defaultValue pins a workflow) and replaces the item's Workflow inputs box
  // (plugin-bdi-<id>.workflow_inputs) with a panel of the chosen workflow's
  // prompts, loaded from the Runbook Workflows webhook. Every answer is written
  // back to workflow_inputs as JSON, {"<step key>": {"<input>": value}}, which
  // is what the form submits; required prompts are required in the panel.
  var survey = this.survey;
  var done = this.returnResult.bind(this);
  if (!survey) { done("error: no survey instance is available to the form function."); return; }
  if (survey.cbServerWorkflowItems) { done("ready"); return; }
  var items = {};
  survey.cbServerWorkflowItems = items;

  var HOOK = "/api/v3/cmp/inboundWebHooks/runbook-workflows/run/";
  var WORKFLOW_RE = /^plugin-bdi-[^.]+\.workflow$/;
  // Inserted question names: cbwf_<item>__<step key>__<input>. Not named
  // plugin-bdi-..., so the submit does not treat them as plug-in inputs.
  var PREFIX = "cbwf_";

  function escapeHtml(value) {
    return String(value === undefined || value === null ? "" : value)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function query(values) {
    return Object.keys(values).map(function (key) {
      return encodeURIComponent(key) + "=" + encodeURIComponent(values[key] === undefined || values[key] === null ? "" : values[key]);
    }).join("&");
  }
  function readJson(response) {
    return response.text().then(function (text) {
      var body;
      try { body = JSON.parse(text); } catch (e) { body = { error: "non-JSON reply (HTTP " + response.status + "): " + text.slice(0, 300) }; }
      if (!body || typeof body !== "object") body = { error: "unexpected reply (HTTP " + response.status + ")" };
      if (!response.ok && !body.error) body.error = "HTTP " + response.status;
      return body;
    });
  }
  function itemKey(question) { return String(question.name).split(".")[0]; }
  function blank(value) {
    return value === undefined || value === null || value === "" || (Array.isArray(value) && !value.length);
  }

  // Renames the webhook's questions (<step>__<input>) so two items never clash,
  // and records which step and input each one answers.
  function rename(entry, elements) {
    var tag = PREFIX + entry.key.replace(/[^A-Za-z0-9]/g, "_");
    (elements || []).forEach(function (element) {
      if (element.type === "panel") {
        element.name = tag + "_" + element.name;
        rename(entry, element.elements);
        return;
      }
      var parts = String(element.name).split("__");
      var step = parts.shift();
      var name = tag + "__" + element.name;
      entry.answers[name] = { step: step, input: parts.join("__") };
      element.name = name;
    });
    return elements;
  }

  // Writes the panel's answers to the item's workflow_inputs as JSON.
  function write(entry) {
    var values = {};
    Object.keys(entry.answers).forEach(function (name) {
      var value = survey.getValue(name);
      if (blank(value)) return;
      var target = entry.answers[name];
      values[target.step] = values[target.step] || {};
      values[target.step][target.input] = value;
    });
    if (Object.keys(values).length) { entry.inputs.value = JSON.stringify(values); } else { entry.inputs.clearValue(); }
  }

  function setPanel(entry, spec, notes) {
    var panel = entry.panel;
    panel.elements.slice().forEach(function (element) { panel.removeElement(element); });
    entry.answers = {};
    var elements = [];
    if (notes) elements.push({ type: "html", name: PREFIX + entry.key.replace(/[^A-Za-z0-9]/g, "_") + "_notes", html: notes });
    elements = elements.concat(rename(entry, (spec && spec.elements) || []));
    elements.forEach(function (json) {
      // Built in full before it joins the page, so the first render has every property.
      var element = Survey.Serializer.createClass(json.type);
      element.fromJSON(json);
      if (!element.name) element.name = json.name;
      panel.addElement(element);
    });
    panel.visible = elements.length > 0;
    write(entry);
  }

  function stepsHtml(spec) {
    var steps = (spec && spec.steps) || [];
    if (!steps.length) return "";
    var items = steps.map(function (step) {
      return "<li><strong>" + escapeHtml(step.name) + "</strong> <span class=\"text-muted\">(" +
        escapeHtml(step.type) + ": " + escapeHtml(step.action) + ")</span></li>";
    }).join("");
    var lead = spec.description ? "<p>" + escapeHtml(spec.description) + "</p>" : "";
    return lead + "<p>Runs these steps in order on the new VM:</p><ol>" + items + "</ol>";
  }

  function load(entry) {
    var workflow = entry.workflow.value;
    var mine = ++entry.request;
    entry.blocking = "";
    if (blank(workflow)) { setPanel(entry, null, ""); return; }
    setPanel(entry, null, "<p class=\"custom-order-form-loading\">Loading the workflow...</p>");
    fetch(HOOK + "?" + query({ source: "prompts", workflow: workflow }), {
      credentials: "same-origin", headers: { "Accept": "application/json" }
    })
      .then(readJson)
      .then(function (reply) {
        if (mine !== entry.request) return;
        if (reply.error || !reply.panel) {
          entry.blocking = reply.error || "Could not load the workflow.";
          setPanel(entry, null, "<p class=\"text-danger\">" + escapeHtml(entry.blocking) + "</p>");
          return;
        }
        var spec = reply.panel;
        var notes = stepsHtml(spec);
        if (spec.blocking && spec.blocking.length) {
          entry.blocking = spec.blocking.join(" ");
          notes += spec.blocking.map(function (reason) { return "<p class=\"text-danger\">" + escapeHtml(reason) + "</p>"; }).join("");
        }
        if (!spec.elements || !spec.elements.length) notes += "<p>This workflow asks for nothing.</p>";
        setPanel(entry, spec, notes);
      })
      .catch(function (error) {
        if (mine !== entry.request) return;
        entry.blocking = "Could not load the workflow: " + error;
        setPanel(entry, null, "<p class=\"text-danger\">" + escapeHtml(entry.blocking) + "</p>");
      });
  }

  function attach(question) {
    var key = itemKey(question);
    if (items[key]) return;
    var container = question.parent;
    if (!container || !container.addElement) return;
    var inputs = survey.getQuestionByName(key + ".workflow_inputs");
    if (!inputs) {
      // The form has no Workflow inputs question: add a hidden one, so the answers are submitted.
      inputs = Survey.Serializer.createClass("comment");
      inputs.name = key + ".workflow_inputs";
      container.addElement(inputs, container.elements.indexOf(question) + 1);
    }
    inputs.visible = false;
    var panel = Survey.Serializer.createClass("panel");
    panel.name = PREFIX + key.replace(/[^A-Za-z0-9]/g, "_") + "_prompts";
    panel.fromJSON({ title: "Workflow inputs", description: "What the workflow's steps ask for. Everything else is set in the workflow." });
    var host = inputs.parent && inputs.parent.addElement ? inputs.parent : container;
    host.addElement(panel, host.elements.indexOf(inputs) + 1);
    var entry = { key: key, workflow: question, inputs: inputs, panel: panel, answers: {}, request: 0, blocking: "" };
    items[key] = entry;
    load(entry);
  }

  function scan() {
    survey.getAllQuestions().forEach(function (question) {
      if (WORKFLOW_RE.test(String(question.name))) attach(question);
    });
  }

  survey.onValueChanged.add(function (sender, options) {
    if (WORKFLOW_RE.test(String(options.name))) {
      var entry = items[itemKey(options.question || { name: options.name })];
      if (entry) load(entry);
      return;
    }
    if (String(options.name).indexOf(PREFIX) !== 0) return;
    Object.keys(items).forEach(function (key) {
      if (items[key].answers[options.name]) write(items[key]);
    });
  });
  survey.onValidateQuestion.add(function (sender, options) {
    if (!WORKFLOW_RE.test(String(options.name))) return;
    var entry = items[itemKey(options.question || { name: options.name })];
    if (entry && entry.blocking) options.error = entry.blocking;
  });
  survey.onQuestionAdded.add(function () { setTimeout(scan, 0); });
  scan();
  done("ready");
}
